<script setup lang="ts">
// 思考过程展示 —— 渲染 reasoning 模型的 reasoningContent(深度思考内容)。
// 极简样式:一行灰色头部(大脑图标 + 状态 + 展开箭头),点击展开;
// 展开后的思考正文比正文气泡字号更小、整体灰化,与最终回答区分。
import { ref, watch } from 'vue'
import MarkdownMessage from './MarkdownMessage.vue'

const props = defineProps<{
  /** 思考内容(Markdown 文本) */
  content: string
  /** 是否仍在流式接收 reasoningContent(true=正在思考中,false=思考已完成) */
  thinking?: boolean
}>()

// 展开态跟随 thinking:正在思考时自动展开(实时看到思考流),思考结束后自动折叠。
// 用 watch(immediate) 同步而非 computed,留出手动开合空间——下一次 thinking 变化前用户可自行展开/收起已完成的卡。
const expanded = ref(false)
watch(() => props.thinking, (v) => { expanded.value = v === true }, { immediate: true })
</script>

